 static class MotionPauseTests {
  static void Check(bool value,string message){if(!value)throw new Exception(message);}
  public static async Task Core(string folder){Directory.CreateDirectory(folder);string source=Path.Combine(folder,"source.mp4");StudioMedia.Run("-v error -y -f lavfi -i testsrc2=size=640x360:rate=30 -f lavfi -i sine=frequency=440:sample_rate=48000 -t 4 -c:v libx264 -preset ultrafast -pix_fmt yuv420p -c:a aac "+Media.Q(source),CancellationToken.None);
   var doc=StudioMedia.Import(source);doc.Style.Background="solid";doc.Style.ColorA="#CDE9E1";doc.Style.AutoZoom=false;doc.IndependentCursor=true;doc.Pointer=new List<PointerSample>{new PointerSample {Time=0,X=.4,Y=.5,Visible=true},new PointerSample {Time=2,X=.6,Y=.5,Visible=true,Segment=1}};
   var clip=new ScreenMotionClip {Start=.2,End=3.8};doc.ScreenMotions.Add(clip);doc.Validate();Check(Math.Abs(ScreenMotionModels.At(doc,.2).RotationY)<.001&&Math.Abs(ScreenMotionModels.At(doc,2).RotationY+18)<.001&&Math.Abs(ScreenMotionModels.At(doc,3.8).RotationY)<.001,"3D animation envelope");
   var rect=new D.RectangleF(130,100,400,220);var identity=new ScreenProjection(rect,new ScreenMotionState(),660,420);Check(identity.Identity(rect),"Identity projection");var ortho=new ScreenProjection(rect,new ScreenMotionState {RotationY=60,Perspective=0},660,420);Check(Math.Abs(ortho.Project(rect.Right,210).X-ortho.Project(rect.X,210).X-200)<.001,"Orthographic 60 degree projection");
   foreach(double perspective in new[]{0,.65,2}){var projection=new ScreenProjection(rect,new ScreenMotionState {RotationX=50,RotationY=-55,RotationZ=30,Perspective=perspective,Scale=2.5,X=.3,Y=.7},660,420);foreach(var point in new[]{new D.PointF(130,100),new D.PointF(530,320),new D.PointF(300,180)}){var mapped=projection.Project(point.X,point.Y);var back=projection.Unproject(mapped.X,mapped.Y);Check(Math.Abs(back.X-point.X)+Math.Abs(back.Y-point.Y)<.001,"Perspective inverse round trip");}}
   foreach(double x in new[]{0,.5,1})foreach(double y in new[]{0,.5,1}){var p=new ScreenProjection(rect,new ScreenMotionState {X=x,Y=y,RotationX=60,RotationY=-60,Perspective=2,Scale=4},660,420);var corner=p.Project(rect.Right,rect.Bottom);Check(EditDocument.Finite(corner.X)&&EditDocument.Finite(corner.Y),"Extreme perspective near-plane clamp");}
   var saved=Path.Combine(folder,"screen3d.dogscwin");doc.Save(saved);var restored=EditDocument.Deserialize(File.ReadAllText(saved));restored.Validate();Check(restored.ScreenMotions.Count==1&&restored.ScreenMotions[0].Target.RotationY==-18,"3D persistence");var legacy=EditDocument.Deserialize(doc.Serialize());legacy.ScreenMotions=null;legacy.Validate();Check(legacy.ScreenMotions.Count==0,"Older project compatibility");var bad=EditDocument.Deserialize(doc.Serialize());bad.ScreenMotions.Add(new ScreenMotionClip {Start=1,End=2});bool rejected=false;try{bad.Validate();}catch{rejected=true;}Check(rejected,"Overlapping motion validation");bad=EditDocument.Deserialize(doc.Serialize());bad.ScreenMotions[0].Target.RotationY=double.NaN;rejected=false;try{bad.Validate();}catch{rejected=true;}Check(rejected,"Non-finite motion validation");
   var pointer=doc.TimelinePointer();Check(pointer.Last().Segment!=pointer.First().Segment,"Pause cursor segment preserved through editing");using(var evaluator=new MotionEvaluator(doc)){var cursor=evaluator.CursorAt(2.01);Check(Math.Abs(cursor.X-.6)<.01,"Cursor smoothing crosses pause boundary");}
   using(var input=new MemoryStream(StudioMedia.Frame(source,2,640)))using(var image=new D.Bitmap(input))using(var canvas=new D.Bitmap(960,540,PixelFormat.Format32bppArgb))using(var graphics=D.Graphics.FromImage(canvas))using(var motion=new MotionEvaluator(doc)){graphics.SmoothingMode=SmoothingMode.AntiAlias;graphics.InterpolationMode=InterpolationMode.HighQualityBicubic;StudioRenderer.Draw(graphics,image,doc,motion,2,960,540,null,canvas);Check(canvas.GetPixel(3,3).ToArgb()==ColorTranslator.FromHtml(doc.Style.ColorA).ToArgb(),"Background moved with tilted screen");canvas.Save(Path.Combine(folder,"screen3d-frame.png"),ImageFormat.Png);}
   await Task.Run(()=>StudioRenderer.Export(doc,Path.Combine(folder,"screen3d.mp4"),720,6,(v,t)=>{},CancellationToken.None));var exported=StudioMedia.Import(Path.Combine(folder,"screen3d.mp4"));Check(exported.Audio&&Math.Abs(exported.Duration-doc.Length)<.2,"3D export duration/audio");
   string[] pieces={Path.Combine(folder,"audio-a.mp4"),Path.Combine(folder,"audio-b.mp4")};for(int i=0;i<2;i++)StudioMedia.Run("-v error -y -f lavfi -i color=c="+(i==0?"red":"green")+":size=320x180:rate=60 -f lavfi -i sine=frequency="+(i==0?440:880)+":sample_rate=48000 -t 1 -c:v libx264 -preset ultrafast -c:a aac -g 60 -movflags +frag_keyframe+empty_moov+default_base_moof+negative_cts_offsets -frag_duration 500000 "+Media.Q(pieces[i]),CancellationToken.None);
   string merged=Path.Combine(folder,"audio-joined.mp4");await RecordingTake.Assemble(pieces,merged,Path.Combine(folder,"audio.ffconcat"));var joined=StudioMedia.Import(merged);Check(joined.Audio&&Math.Abs(joined.Duration-2)<.15&&Math.Abs(joined.FrameRate-60)<.1,"Pause audio assembly");StudioMedia.Run("-v error -i "+Media.Q(merged)+" -f null -",CancellationToken.None);
   File.WriteAllText(Path.Combine(folder,"core-results.txt"),"PASS: 3D geometry and inverse projection, animation envelopes, save/reopen and old projects, overlap/NaN rejection, independent cursor boundaries, 720p preview/export with audio, paused segment assembly with AAC audio.\n");
  }
 }
 public partial class Studio {
  public async Task VerifyScreenMotionInterface(string folder){await Load(Path.Combine(folder,"screen3d.dogscwin"));tab="运镜";motionTab="屏幕 3D";selectedCut=selectedZoom=selectedOverlay=selectedScreen=-1;BuildRail();BuildInspector();SelectScreenMotion(0);await SettleEffects();UI.SaveImage((FrameworkElement)Window.Content,Path.Combine(folder,"screen3d-editor.png"));
   var angle=UI.Descendants<TextBox>(inspector).Single(b=>b.Name=="ScreenTiltX");angle.Text="24°";angle.RaiseEvent(new System.Windows.Input.KeyboardFocusChangedEventArgs(System.Windows.Input.Keyboard.PrimaryDevice,0,angle,null){RoutedEvent=System.Windows.Input.Keyboard.LostKeyboardFocusEvent});if(Doc.ScreenMotions[0].Target.RotationX!=24)throw new Exception("3D tilt control");History(false);if(Doc.ScreenMotions[0].Target.RotationX!=12)throw new Exception("3D undo");History(true);if(Doc.ScreenMotions[0].Target.RotationX!=24)throw new Exception("3D redo");SelectScreenMotion(0);Delete();if(Doc.ScreenMotions.Count!=0)throw new Exception("3D delete");History(false);if(Doc.ScreenMotions.Count!=1)throw new Exception("3D undo deletion");selectedScreen=-1;Seek(0);AddScreenMotion();if(Doc.ScreenMotions.Count!=2||Doc.ScreenMotions.Last().End>.2+.001)throw new Exception("3D add at playhead avoids overlap");SelectScreenMotion(0);Seek(2);double beforeSplit=ScreenMotionModels.At(Doc,2.4).RotationY;int motionCount=Doc.ScreenMotions.Count;Split();if(Doc.ScreenMotions.Count!=motionCount+1||Math.Abs(ScreenMotionModels.At(Doc,2.4).RotationY-beforeSplit)>.0001)throw new Exception("3D split changed motion");Doc.Validate();History(false);Doc.Save(Path.Combine(folder,"ui-screen3d.dogscwin"));SelectScreenMotion(0);Find<ScrollViewer>("InspectorScroll").ScrollToVerticalOffset(230);await SettleEffects();UI.SaveImage((FrameworkElement)Window.Content,Path.Combine(folder,"screen3d-tilt-controls.png"));var soft=new OverlayClip {Start=.2,End=3.8,Kind="blur",Name="3D 柔化"};Doc.Overlays.Add(soft);SelectEffect(Doc.Overlays.Count-1);Seek(2);await SettleEffects();DrawEffectGuides();if(!overlayGuides.Children.OfType<System.Windows.Shapes.Polygon>().Any())throw new Exception("Projected softening guide missing");var grip=overlayGuides.Children.OfType<Thumb>().Single();double before=soft.Width;grip.RaiseEvent(new DragStartedEventArgs(0,0));grip.RaiseEvent(new DragDeltaEventArgs(20,10));grip.RaiseEvent(new DragCompletedEventArgs(20,10,false));if(soft.Width<=before)throw new Exception("Projected softening resize");await SettleEffects();UI.SaveImage((FrameworkElement)Window.Content,Path.Combine(folder,"screen3d-softening.png"));dirty=false;File.WriteAllText(Path.Combine(folder,"ui-results.txt"),"PASS: 3D inspector controls, actual rendered editor, add/delete, undo/redo, timeline selection and project save.\n");}
 }
 public partial class RecorderWindow {
  public async Task VerifyStaticRegion(string folder){var surface=new Window {Title="Synthetic Region Pause Verification",Width=700,Height=480,WindowStyle=WindowStyle.None,Background=UI.Brush("#193E51"),Topmost=true,WindowStartupLocation=WindowStartupLocation.CenterScreen};RecordingTake test=null;
   try{surface.Show();await Task.Delay(100);Native.Point origin=new Native.Point();ClientToScreen(new WindowInteropHelper(surface).Handle,ref origin);var region=new D.Rectangle(origin.X+32,origin.Y+32,320,180);string file=Path.Combine(folder,"region-paused.mp4");test=new RecordingTake(IntPtr.Zero,region,60,null,file);await test.Resume(message=>{});await Task.Delay(900);await test.Pause();if(test.CommittedSeconds<.5)throw new Exception("Static region did not preserve elapsed frames");double seconds=test.Seconds;await Task.Delay(600);if(test.Seconds!=seconds)throw new Exception("Static region paused clock");await test.Resume(message=>{});await Task.Delay(700);await test.Finish();var doc=StudioMedia.Import(file);if(doc.Width!=320||doc.Height!=180||Math.Abs(doc.FrameRate-60)>.1)throw new Exception("Static region frame size/rate");using(var bytes=new MemoryStream(StudioMedia.Frame(file,.25,320)))using(var image=new D.Bitmap(bytes)){var c=image.GetPixel(5,5);if(Math.Abs(c.R-25)+Math.Abs(c.G-62)+Math.Abs(c.B-81)>30)throw new Exception("Desktop duplication captured the wrong region");}File.AppendAllText(Path.Combine(folder,"pause-results.txt"),"PASS: selected opaque synthetic region captured at 320x180/60 FPS, including static frames, pause/resume and stitching; "+test.Backend+".\n");}
   finally{if(test!=null)test.Dispose();surface.Close();}
  }  public async Task VerifyPause(int rate,string folder,bool stopPaused=false,bool failResume=false){testingCapture=true;frameRates.SelectedItem=rate;var fill=new System.Windows.Controls.Border {Background=UI.Brush("#D63040")};var surface=new Window {Title="Windows Pause Verification "+rate,Width=440,Height=280,Content=fill,WindowStartupLocation=WindowStartupLocation.CenterScreen,Topmost=true};
   try{surface.Show();Show();SelectMode("窗口");sources.SelectedItem=sources.Items.Cast<WindowSource>().First(w=>w.Title==surface.Title);ToggleRecording();var deadline=System.Diagnostics.Stopwatch.StartNew();while((capture==null||busy)&&recordingFailure==null&&deadline.Elapsed.TotalSeconds<45)await Task.Delay(100);if(recordingFailure!=null)throw recordingFailure;if(capture==null||busy)throw new Exception("Pause test capture did not start");await Task.Delay(1100);await ChangePause();if(!take.IsPaused||!IsRecording||!pauseButton.IsEnabled||!start.IsEnabled)throw new Exception("Paused UI state");double savedSeconds=take.Seconds;int pointerCount=points.Count;fill.Background=UI.Brush("#FF00FF");await Task.Delay(1300);if(take.Seconds!=savedSeconds||points.Count!=pointerCount)throw new Exception("Paused clock or pointer continued");UI.SaveImage((FrameworkElement)Content,Path.Combine(folder,"paused-recorder-"+rate+".png"));
    if(failResume){surface.Close();bool failed=false;try{await ChangePause();}catch{failed=true;}if(!failed||!take.IsPaused||!IsRecording)throw new Exception("Failed resume discarded committed take");}
    if(!stopPaused){fill.Background=UI.Brush("#238B52");await ChangePause();if(take.IsPaused||capture==null)throw new Exception("Resume failed");await Task.Delay(900);await ChangePause();double stable=take.Seconds;fill.Background=UI.Brush("#FF00FF");await Task.Delay(700);if(take.Seconds!=stable)throw new Exception("Second pause clock");fill.Background=UI.Brush("#287FD1");await ChangePause();await Task.Delay(900);}
    await Stop();if(recordingFailure!=null)throw recordingFailure;var doc=StudioMedia.Import(sourcePath);if(doc.Duration<.5||Math.Abs(doc.FrameRate-rate)>.1)throw new Exception("Pause save frame rate");if(studio.Doc.Source!=sourcePath||studio.Doc.Pointer.Any(p=>p.Time>doc.Duration))throw new Exception("Pause project timeline");
    for(double t=.1;t<doc.Duration-.05;t+=.17)using(var bytes=new MemoryStream(StudioMedia.Frame(sourcePath,t,100)))using(var image=new D.Bitmap(bytes)){var color=image.GetPixel(50,image.Height/2);if(color.R>180&&color.B>180&&color.G<70)throw new Exception("Paused magenta frame appears in output at "+t);}
    File.AppendAllText(Path.Combine(folder,"pause-results.txt"),"PASS: "+rate+" FPS "+(failResume?"failed resume then stop/save":stopPaused?"stop while paused":"two pause/resume cycles")+"; excluded paused frames, frozen time/points, stitched recording and saved/reopened project; "+doc.Duration.ToString("F3")+" seconds.\n");
   }finally{if(surface.IsVisible)surface.Close();timer.Stop();if(take!=null){take.Dispose();take=null;}busy=false;if(IsVisible)Close();}
  }
 }
